import { useState, useEffect } from 'react';

interface Task {
  id: number;
  title: string;
  status: 'pending' | 'in-progress' | 'completed';
  priority: 'low' | 'medium' | 'high';
}

// Mock API function - simulates network delay
const fetchTasks = async (): Promise<Task[]> => {
  await new Promise(resolve => setTimeout(resolve, 1000));

  // Simulate random errors (20% chance)
  if (Math.random() < 0.2) {
    throw new Error('Failed to fetch tasks from server');
  }

  return [
    { id: 1, title: 'Review pull requests', status: 'pending', priority: 'high' },
    { id: 2, title: 'Update documentation', status: 'in-progress', priority: 'medium' },
    { id: 3, title: 'Fix login bug', status: 'completed', priority: 'high' },
    { id: 4, title: 'Setup CI/CD pipeline', status: 'pending', priority: 'low' },
    { id: 5, title: 'Refactor API endpoints', status: 'in-progress', priority: 'medium' },
    { id: 6, title: 'Write unit tests', status: 'pending', priority: 'medium' },
  ];
};

export default function TaskDashboard() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string>('all');

  const loadTasks = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await fetchTasks();
      setTasks(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadTasks();
  }, []);

  const filteredTasks = statusFilter === 'all' 
    ? tasks 
    : tasks.filter(task => task.status === statusFilter);

  if (loading) {
    return <div className="loading">Loading tasks...</div>;
  }

  if (error) {
    return (
      <div className="error">
        <p>Error: {error}</p>
        <button onClick={loadTasks}>Retry</button>
      </div>
    );
  }

  return (
    <div className="task-dashboard">
      <div className="header">
        <h1>Task Dashboard</h1>
        <button onClick={loadTasks}>Refresh</button>
      </div>

      <div className="filters">
        <label>
          Filter by status:
          <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)}>
            <option value="all">All</option>
            <option value="pending">Pending</option>
            <option value="in-progress">In Progress</option>
            <option value="completed">Completed</option>
          </select>
        </label>
      </div>

      <div className="task-list">
        {filteredTasks.map(task => (
          <div key={task.id} className="task-item">
            <h3>{task.title}</h3>
            <span className="status">{task.status}</span>
            <span className="priority">{task.priority}</span>
          </div>
        ))}
      </div>
    </div>
  );
}
